INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-ca8d-7201-bbd9-4643a396b59e'::uuid, '019f9df7-a2a2-7941-9e48-3d4dda1f252c'::uuid, 'The probability that a student is in a sports club is 0.4, and the probability that a student is a leader is 0.25. Explain why the probability of being in a sports club or being a leader cannot always be found by simply adding these two probabilities.', 'Because the two events can overlap (are not mutually exclusive), leading to double counting.', 'P(A ∪ B) = P(A) + P(B) - P(A ∩ B). Simple addition is only valid when the events are mutually exclusive (no overlap).', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.525Z'::timestamptz, '2026-08-15T07:50:40.525Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a067f4-c2da-7a38-b20a-55284c39be05'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'Mrs Ram bought a washing machine for $390 during a sale. The shop was having a 35% discount on all appliances.

Find the usual selling price of the washing machine before the sale.', '$600', 'After a 35% discount, the customer pays 65% of the usual price.
65% of usual price = $390
Usual price = 390 / 0.65 = $600.', 'Easy', '{"tags":"sass-2022-p1,q1","subtopic":"Reverse percentages","question_type":"open","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-03T15:48:09.047Z'::timestamptz, '2026-09-03T15:48:09.047Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a067f4-c2ed-734f-a965-803793bd5041'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'A light on a computer comes on for 26 700 microseconds. One microsecond is 10^-6 seconds.

Work out the length of time, in seconds, that the light is on in standard form.', '2.67 x 10^-2 s', '26 700 microseconds = 26 700 x 10^-6 s
= 2.67 x 10^4 x 10^-6 s
= 2.67 x 10^-2 s.', 'Easy', '{"tags":"sass-2022-p1,q3a","subtopic":"Standard form","question_type":"open","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-03T15:48:09.069Z'::timestamptz, '2026-09-03T15:48:09.069Z'::timestamptz) ON CONFLICT (id) DO NOTHING;